export function SuggestedPrompts({
  onSelect,
  initialPrompts,
  model,
}: {
  onSelect: (text: string) => void;
  initialPrompts?: readonly StarterPrompt[];
  /** Currently selected chat model; enables the personalized opening. */
  model?: Model<Api> | null;
}) {
  const [prompts, setPrompts] = useState(() => (
    initialPrompts ? [...initialPrompts] : pickDiverseStarterPrompts(STARTER_PROMPTS, 3)
  ));
  const [greeting, setGreeting] = useState<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  // With a usable model, replace the generic header with a greeting tailored
  // to the learner's history and surface model-suggested next steps. Without
  // one (or without history) the generic experience stays.
  useEffect(() => {
    if (!model) return;
    let cancelled = false;
    getTailoredOpening(model)
      .then((opening) => {
        if (cancelled || !opening) return;
        setGreeting(opening.greeting);
        if (opening.prompts.length > 0) {
          setPrompts((prev) => {
            const seen = new Set(prev.map((p) => p.text));
            return [...opening.prompts.filter((p) => !seen.has(p.text)), ...prev];
          });
        }
      })
      .catch((error) => {
        console.warn("Tailored opening unavailable:", error);
      });

  oauthCallbackRoute,
	downloadRoute,
	termsRoute,
	privacyRoute,
	pricingRoute,
  latestCommitReviewRoute,
	coursesRoute,
	courseJoinRoute,
	courseWorkspaceRoute,
]);

// Shown while a lazily-loaded route chunk is in flight (after defaultPendingMs)
// so navigation doesn't flash a blank screen.
function RoutePending() {
  return (
    <div
      style={{
        display: "flex",
        minHeight: "60vh",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        className={css({
          animation: "spin 1s linear infinite"
        })}
        aria-label="Loading"
        style={{
          width: 28,
          height: 28,
          borderRadius: "9999px",
          border: "3px solid rgba(0,0,0,0.15)",
          borderTopColor: "rgba(0,0,0,0.55)",
        }}
      />
    </div>
  );
}

const browserHistory = createBrowserHistory();
const router = createRouter({
  routeTree,
  history: browserHistory,
  defaultPendingComponent: RoutePending,
});

declare module "@tanstack/react-router" {
  interface Register {
    router: typeof router;
  }
}

function KeatingUiPreferencesSync() {
  const [settings, setSettings] = useState(() => loadKeatingUiSettings());

  useEffect(() => {
    applyKeatingUiTypography(settings.fontFamily);
  }, [settings.fontFamily]);

  useEffect(() => subscribeKeatingUiSettings(setSettings), []);

  return null;
}

export function App() {
  return (
    <>
      <KeatingUiPreferencesSync />
      <RouterProvider router={router} />
    </>
  );
}

