				},
			}],
		})
	);

	mcp.registerResource(
		"keating.page",
		"Current Keating page content visible to the browser.",
		{ uri: "keating://page", mimeType: "text/html" },
		(uri: string) => ({
			contents: [{ uri, mimeType: "text/html", text: document.body.innerHTML }],
		})
	);

	mcp.registerResource(
